238	    @Override
239	    @Transactional
240	    public void saveOwner(Owner owner) throws DataAccessException {
241	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
242	        if (owner.isNew()) {
243	            if (hasIdenticalOwner(owner)) {
244	                throw new DuplicateOwnerException();
245	            }
246	            if (hasOwnerWithSameEmail(owner)) {
247	                throw new DuplicateOwnerException("An owner with the same email address already exists");
248	            }
249	            if (hasReachedDailyRegistrationLimit()) {
250	                throw new DailyOwnerRegistrationLimitExceededException();
251	            }
252	            if (hasReachedCityLimit(owner)) {
253	                throw new CityOwnerLimitExceededException();
254	            }
255	            if (owner.getRegistrationDate() == null) {
256	                owner.setRegistrationDate(LocalDate.now());
257	            }
258	            owner.setCity(resolveCity(owner));
259	            owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
260	            owner.setCustomerCode(generateCustomerCode(owner));
261	            owner.setMembershipTier(resolveMembershipTier());
262	            owner.setNamesakeCount(countNamesakes(owner));
263	            owner.setSharesHousehold(sharesHousehold(owner));
264	            owner.setLocality(resolveLocality(owner));
265	        }
266	        ownerRepository.save(owner);
267	
268	    }
269	
270	    /**
271	     * Generates a customer code for a newly registered owner, formatted as
272	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number
273	     * of owners already in that city, zero-padded to four digits (e.g. {@code LONDON-0007}).
274	     */
275	    private String generateCustomerCode(Owner owner) {
276	        String city = owner.getCity();
277	        long existingInCity = ownerRepository.findAll().stream()
278	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalize(city)))
279	            .count();
280	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
281	    }
282	
283	    /**
284	     * Resolves the city to store for a newly registered owner. If another owner already
285	     * lives in the same city (ignoring letter case and surrounding/repeated whitespace),
286	     * that owner's exact spelling of the city name is reused so a city is stored
287	     * consistently. Otherwise the supplied city is title-cased, i.e. each word is
288	     * capitalized and the remaining letters lower-cased (e.g. {@code "new york"} becomes
289	     * {@code "New York"}). Returns {@code null} for a {@code null} input.
290	     */
291	    private String resolveCity(Owner owner) {
292	        String city = owner.getCity();
293	        if (city == null) {
294	            return null;
295	        }
296	        String normalized = normalize(city);
297	        return ownerRepository.findAll().stream()
298	            .map(Owner::getCity)
299	            .filter(existing -> Objects.equals(normalize(existing), normalized))
300	            .findFirst()
301	            .orElseGet(() -> toTitleCase(city));
302	    }
303	
304	    /**
305	     * Title-cases a value by trimming and collapsing whitespace, then capitalizing the
306	     * first letter of each whitespace-separated word and lower-casing the rest
307	     * (e.g. {@code "  new   YORK "} becomes {@code "New York"}).
308	     */
309	    private static String toTitleCase(String value) {
310	        String collapsed = value.trim().replaceAll("\\s+", " ");
311	        if (collapsed.isEmpty()) {
312	            return collapsed;
313	        }
314	        StringBuilder result = new StringBuilder(collapsed.length());
315	        for (String word : collapsed.split(" ")) {
316	            if (result.length() > 0) {
317	                result.append(' ');
318	            }
319	            result.append(Character.toUpperCase(word.charAt(0)))
320	                .append(word.substring(1).toLowerCase(Locale.ROOT));
321	        }
322	        return result.toString();
323	    }
324	
325	    /**
326	     * The number of owners that receive the founding membership tier. The first
327	     * {@link #FOUNDING_TIER_LIMIT} owners ever created are {@code FOUNDING}; all later
328	     * owners are {@code STANDARD}.
329	     */
330	    private static final long FOUNDING_TIER_LIMIT = 100;
331	
332	    /**
333	     * Resolves the membership tier for a newly registered owner: {@code FOUNDING} while
334	     * fewer than {@link #FOUNDING_TIER_LIMIT} owners exist beforehand, otherwise {@code STANDARD}.
335	     */
336	    private String resolveMembershipTier() {
337	        return ownerRepository.findAll().size() < FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
338	    }
339	
340	    /**
341	     * Counts how many other owners already share the newly registered owner's last name,
342	     * ignoring letter case and surrounding/repeated whitespace. Invoked before the owner
343	     * is persisted, so it reflects the number of namesakes existing at creation time.
344	     */
345	    private int countNamesakes(Owner owner) {
346	        String lastName = normalize(owner.getLastName());
347	        return (int) ownerRepository.findAll().stream()
348	            .filter(existing -> Objects.equals(normalize(existing.getLastName()), lastName))
349	            .count();
350	    }
351	
352	    /**
353	     * Determines whether the newly registered owner shares a household with an existing owner,
354	     * i.e. another owner already has the same address and city (each compared ignoring letter
355	     * case and surrounding/repeated whitespace). Invoked before the owner is persisted, so it
356	     * reflects the state at creation time.
357	     */
358	    private boolean sharesHousehold(Owner owner) {
359	        String address = normalize(owner.getAddress());
360	        String city = normalize(owner.getCity());
361	        return ownerRepository.findAll().stream()
362	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
363	                && Objects.equals(normalize(existing.getCity()), city));
364	    }
365	
366	    /**
367	     * Resolves the locality of a newly registered owner: {@code "local"} if this owner's city
368	     * is the single most common city among the owners that existed beforehand, otherwise
369	     * {@code "remote"}. Cities are compared ignoring letter case and surrounding/repeated
370	     * whitespace. If there are no existing owners, or if two or more cities are tied for the
371	     * highest count (so there is no single most common city), the owner is {@code "remote"}.
372	     * Invoked before the owner is persisted, so it reflects the state at creation time.
373	     */
374	    private String resolveLocality(Owner owner) {
375	        String city = normalize(owner.getCity());
376	        Map<String, Long> cityCounts = ownerRepository.findAll().stream()
377	            .map(existing -> normalize(existing.getCity()))
378	            .filter(Objects::nonNull)
379	            .collect(Collectors.groupingBy(c -> c, Collectors.counting()));
380	        if (cityCounts.isEmpty()) {
381	            return "remote";
382	        }
383	        long highestCount = Collections.max(cityCounts.values());
384	        List<String> mostCommonCities = cityCounts.entrySet().stream()
385	            .filter(entry -> entry.getValue() == highestCount)
386	            .map(Map.Entry::getKey)
387	            .toList();
388	        boolean isSingleMostCommon = mostCommonCities.size() == 1
389	            && Objects.equals(mostCommonCities.get(0), city);
390	        return isSingleMostCommon ? "local" : "remote";
391	    }
392	
393	    /**
394	     * The maximum number of owners that may be registered on a single day (by registration date).
395	     */
396	    private static final long MAX_OWNERS_PER_DAY = 20;
397	
398	    /**
399	     * Returns {@code true} if the number of owners already registered today (by registration date)
400	     * has reached {@link #MAX_OWNERS_PER_DAY}, so that no further owner may be created today.
401	     */
402	    private boolean hasReachedDailyRegistrationLimit() {
403	        LocalDate today = LocalDate.now();
404	        long registeredToday = ownerRepository.findAll().stream()
405	            .filter(existing -> today.equals(existing.getRegistrationDate()))
406	            .count();
407	        return registeredToday >= MAX_OWNERS_PER_DAY;
408	    }
409	
410	    /**
411	     * The maximum number of owners that may live in a single city.
412	     */
413	    private static final long MAX_OWNERS_PER_CITY = 8;
414	
415	    /**
416	     * Returns {@code true} if the owner's city (compared ignoring letter case and surrounding/repeated
417	     * whitespace) already contains {@link #MAX_OWNERS_PER_CITY} owners, so that no further owner may be
418	     * registered in that city.
419	     */
420	    private boolean hasReachedCityLimit(Owner owner) {
421	        String city = normalize(owner.getCity());
422	        if (city == null) {
423	            return false;
424	        }
425	        long ownersInCity = ownerRepository.findAll().stream()
426	            .filter(existing -> Objects.equals(normalize(existing.getCity()), city))
427	            .count();
428	        return ownersInCity >= MAX_OWNERS_PER_CITY;
429	    }
430	
431	    private boolean hasIdenticalOwner(Owner owner) {
432	        return ownerRepository.findAll().stream()
433	            .anyMatch(existing -> isSameOwner(existing, owner));
434	    }
435	
436	    private boolean isSameOwner(Owner existing, Owner owner) {
437	        return Objects.equals(normalizeTelephone(existing.getTelephone()), normalizeTelephone(owner.getTelephone()));
438	    }
439	
440	    /**
441	     * Normalizes a telephone number for storage and duplicate detection by stripping
442	     * everything except digits (e.g. spaces, dashes and parentheses), so that
443	     * {@code "(613) 555-0100"} and {@code "6135550100"} are treated as the same number.
444	     * Returns {@code null} for a {@code null} input.
445	     */
446	    private static String normalizeTelephone(String telephone) {
447	        if (telephone == null) {
448	            return null;
449	        }
450	        return telephone.replaceAll("[^0-9]", "");
451	    }
452	
453	    private boolean hasOwnerWithSameEmail(Owner owner) {
454	        String email = normalize(owner.getEmail());
455	        if (email == null || email.isEmpty()) {
456	            return false;
457	        }
458	        return ownerRepository.findAll().stream()
459	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
460	    }
461	
462	    /**
463	     * Normalizes a value for duplicate detection so that values differing only in
464	     * letter case or in surrounding/repeated whitespace compare as equal. Surrounding
465	     * whitespace is trimmed, internal whitespace runs are collapsed to a single space,
466	     * and the result is lower-cased (e.g. {@code "  john   smith "} and {@code "John Smith"}
467	     * both normalize to {@code "john smith"}). Returns {@code null} for a {@code null} input.
468	     */
469	    private static String normalize(String value) {
470	        if (value == null) {
471	            return null;
472	        }
473	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
474	    }
475	
476	    @Override
477	    @Transactional(readOnly = true)
478	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
479	        return ownerRepository.findByLastName(lastName);
480	    }
481	
482	    @Override
483	    @Transactional(readOnly = true)
484	    public Collection<Visit> findVisitsByPetId(int petId) {
485	        return visitRepository.findByPetId(petId);
486	    }
487	
488	    @Override
489	    @Transactional(readOnly = true)
490	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
491	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
492	    }
493	
494	    private <T> T findEntityById(Supplier<T> supplier) {
495	        try {
496	            return supplier.get();
497	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
498	            // Just ignore not found exceptions for Jdbc/Jpa realization
499	            return null;
500	        }
501	    }
502	
503	}
